/**
 * Builds the browser scripts the connector serves: type-checks each source against the DOM (its
 * own `tsconfig.json`, beside the source), then bundles it with esbuild into a generated module, a
 * string constant the page serves.
 *
 *   npx tsx mcp/sasha-slides/browser-scripts/build.ts          (from the repo root)
 *
 * WHY A CHECKED-IN GENERATED FILE rather than bundling at server start: esbuild is a
 * development dependency of the repo, not a runtime dependency of the connector image
 * (`deploy/package.json`), and a generated TypeScript module is reached through an ordinary
 * import, so `deploy/context-files.ts` ships it with no list to edit. The same pattern as
 * `sasha-icon.generated.ts`. `test/browser-scripts.test.ts` fails when a generated file no
 * longer matches its source, so an edit that skipped this build cannot go unnoticed.
 */
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { build } from "esbuild";

export type BrowserScript = Readonly<{
  /** The source's directory, relative to the connector; it holds the script's own tsconfig.json. */
  directory: string;
  entry: string;
  /** Relative to the connector. */
  generatedModule: string;
  exportName: string;
}>;

export const BROWSER_SCRIPTS: readonly BrowserScript[] = [
  // The account portal's passkey ceremonies, served at /account/passkey.js.
  { directory: "http/passkey-browser", entry: "passkey.ts", generatedModule: "http/passkey-script.generated.ts", exportName: "PASSKEY_SCRIPT" },
  // The /comments/allow page's Google Picker, served at /comments/allow/picker.js.
  { directory: "comment-bot/access-browser", entry: "picker.ts", generatedModule: "comment-bot/picker-script.generated.ts", exportName: "PICKER_SCRIPT" },
];

const CONNECTOR = join(import.meta.dirname, "..");
const REPO_ROOT = join(CONNECTOR, "..", "..");

export function generatedModulePath(script: BrowserScript): string {
  return join(CONNECTOR, script.generatedModule);
}

/** The generated module's full text, from the current source. */
export async function renderScriptModule(script: BrowserScript): Promise<string> {
  const source = join(CONNECTOR, script.directory, script.entry);
  const result = await build({
    // Fixed, so the source path esbuild writes into the output does not depend on the caller's cwd.
    absWorkingDir: REPO_ROOT,
    entryPoints: [source],
    bundle: true,
    format: "iife",
    platform: "browser",
    target: "es2020",
    minify: false,
    write: false,
    logLevel: "error",
  });
  const code = result.outputFiles[0]?.text;
  if (code === undefined) throw new Error(`esbuild produced no output for ${source}`);
  return `// Generated by browser-scripts/build.ts from ${script.directory}/${script.entry}. Do not edit.\nexport const ${script.exportName} = ${JSON.stringify(code)};\n`;
}

async function main(): Promise<void> {
  for (const script of BROWSER_SCRIPTS) {
    // esbuild strips types without checking them, so the check is its own failing step first.
    execFileSync(join(REPO_ROOT, "node_modules", ".bin", "tsc"), ["--noEmit", "-p", join(CONNECTOR, script.directory)], { stdio: "inherit" });
    writeFileSync(generatedModulePath(script), await renderScriptModule(script));
    process.stdout.write(`wrote ${generatedModulePath(script)}\n`);
  }
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === import.meta.filename) void main();
